package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierTable struct {
	TierEntry struct {
		TierLimit decimal.Decimal
		TierRate  decimal.Decimal
	}
}

// working-storage
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

// FD record
var SrId string
var SrSales decimal.Decimal = decimal.Zero

// tier table 1-based
var TierLimits [5]decimal.Decimal
var TierRates [5]decimal.Decimal

// file handling
var inputFile *os.File
var inputScanner *bufio.Scanner
var inputOpen bool

func parseSalesField(s string) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.Zero
	}
	t := strings.TrimSpace(s)
	// keep only digits (should be digits only)
	// but TrimSpace already leaves digits
	d, err := decimal.NewFromString(t)
	if err != nil {
		filtered := ""
		for _, ch := range t {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered == "" {
			return decimal.Zero
		}
		d, _ = decimal.NewFromString(filtered)
	}
	return d.Shift(-2)
}

func fitDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	isNeg := v.IsNegative()
	vAbs := v.Abs()
	scaled := vAbs.Shift(int32(scale)).Truncate(0)
	s := scaled.StringFixed(0)
	capLen := intDigits + scale
	if len(s) > capLen {
		s = s[len(s)-capLen:]
	}
	d, _ := decimal.NewFromString(s)
	d = d.Shift(int32(-scale))
	if isNeg {
		d = d.Neg()
	}
	return d
}

func storeRounded(src decimal.Decimal, intDigits, scale int) decimal.Decimal {
	rnd := src.Round(int32(scale))
	return fitDecimal(rnd, intDigits, scale)
}

func storeInt(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if mod == 0 {
		return v
	}
	r := v % mod
	if r < 0 {
		r = -r
	}
	return r
}

func formatEdited(v decimal.Decimal, pic string) string {
	vAbs := v.Abs()
	dot := strings.Index(pic, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	scale := fracDigits
	vQuant := vAbs.Round(int32(scale))
	scaled := vQuant.Shift(int32(scale)).Truncate(0)
	s := scaled.StringFixed(0)
	totalLen := intDigits + scale
	if len(s) > totalLen {
		s = s[len(s)-totalLen:]
	} else if len(s) < totalLen {
		s = strings.Repeat("0", totalLen-len(s)) + s
	}
	var intStr, fracStr string
	if scale > 0 {
		intStr = s[:intDigits]
		fracStr = s[intDigits:]
	} else {
		intStr = s
		fracStr = ""
	}
	outInt := make([]rune, len(intPic))
	suppressed := true
	di := 0
	for i, pc := range intPic {
		if pc == 'Z' || pc == '9' {
			d := intStr[di]
			di++
			if pc == 'Z' {
				if suppressed && d == '0' {
					outInt[i] = ' '
				} else {
					outInt[i] = rune(d)
					suppressed = false
				}
			} else { // '9'
				outInt[i] = rune(d)
				suppressed = false
			}
		} else if pc == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else {
			outInt[i] = pc
		}
	}
	res := string(outInt)
	if scale > 0 {
		res += "." + fracStr
	}
	// negative handling not needed for this program
	return res
}

func formatUneditedInt(v int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	r := v % mod
	if r < 0 {
		r = -r
	}
	return fmt.Sprintf("%0*d", digits, r)
}

func InitPara() {
	d, _ := decimal.NewFromString("1000.00")
	TierLimits[1] = d
	d, _ = decimal.NewFromString("2.50")
	TierRates[1] = d
	d, _ = decimal.NewFromString("5000.00")
	TierLimits[2] = d
	d, _ = decimal.NewFromString("4.00")
	TierRates[2] = d
	d, _ = decimal.NewFromString("20000.00")
	TierLimits[3] = d
	d, _ = decimal.NewFromString("5.50")
	TierRates[3] = d
	d, _ = decimal.NewFromString("999999.99")
	TierLimits[4] = d
	d, _ = decimal.NewFromString("7.25")
	TierRates[4] = d
}

func ReadPara() {
	if !inputOpen || inputScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if inputScanner.Scan() {
		line := inputScanner.Text()
		if len(line) < 12 {
			line += strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		SrId = line[0:4]
		salesStr := line[4:12]
		SrSales = parseSalesField(salesStr)
		WsEofFlag = "N"
	} else {
		if err := inputScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && WsTier == 0; WsIdx++ {
		if SrSales.Cmp(TierLimits[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
	}
	rate := TierRates[WsTier]
	product := SrSales.Mul(rate)
	divided := product.Shift(-2)
	WsComm = storeRounded(divided, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = fitDecimal(WsTotal, 9, 2)
	WsCount = storeInt(WsCount+1, 3)
	WsSalesEd = formatEdited(SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")
	tierStr := formatUneditedInt(WsTier, 1)
	line := SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Println(line)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Println(line)
}

func main() {
	InitPara()
	f, err := os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		SummaryPara()
		return
	}
	inputFile = f
	inputOpen = true
	defer func() {
		f.Close()
		inputOpen = false
	}()
	inputScanner = bufio.NewScanner(f)
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	inputScanner.Buffer(buf, maxCap)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}
